examples.code:
# Written by hand
class ProductPlain:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def __repr__(self):
        return f"ProductPlain(name={self.name!r}, price={self.price!r})"

    def __eq__(self, other):
        if not isinstance(other, ProductPlain):
            return NotImplemented
        return self.name == other.name and self.price == other.price

# Equivalent, via @dataclass
from dataclasses import dataclass

@dataclass
class Product:
    name: str
    price: float

p1 = Product("Widget", 9.99)
p2 = Product("Widget", 9.99)
print(p1)             # Product(name='Widget', price=9.99)
print(p1 == p2)        # True

from dataclasses import dataclass

@dataclass(frozen=True)
class Coordinate:
    lat: float
    lon: float

origin = Coordinate(0.0, 0.0)
print(origin)          # Coordinate(lat=0.0, lon=0.0)

try:
    origin.lat = 5.0
except Exception as e:
    print(type(e).__name__, "--", e)   # FrozenInstanceError -- cannot assign to field 'lat'

# frozen=True also makes it usable as a dict key / set member:
visited = {Coordinate(0.0, 0.0), Coordinate(1.5, 2.5)}
print(len(visited))   # 2

